def _with_overrides(rules, overrides):
    """نسخةٌ من أسطر إسرائيل بقواعدها المشتركة وتعديلات نشرتها وحدها."""
    return tuple(
        {**row, "period_overrides": overrides.get(row["code"], {})}
        for row in rules
    )


