def _rule_defaults(row, position):
    """حقولُ السطر بقيمها الافتراضية — القاعدةُ وحدها مطلوبةٌ في كل سطر."""
    return {
        "name": row["name"],
        "service_code": row["service_code"],
        "cadence": row.get("cadence", "service"),
        "rule_kind": row["rule_kind"],
        "rule_day": row.get("rule_day"),
        "rule_month": row.get("rule_month"),
        "conditions": row.get("conditions", {}),
        "is_generated": row.get("is_generated", True),
        "electronic_extension_days": row.get("electronic_extension_days", 0),
        "period_overrides": row.get("period_overrides", {}),
        "needs_review": row.get("needs_review", False),
        "source_url": row["source_url"],
        "position": position,
    }


def seed_deadline_schedules(apps, schema_editor):
    """يزرع لائحتَي النظامين وسقفَ التقرير المفصّل — **idempotent**.

    بياناتُ منصّةٍ لا بياناتُ مكتب (بلا `tenant`): الموعدُ واحدٌ لكل المكاتب،
    والنسخةُ لا تُعدَّل — تصحيحُ لائحةٍ منشورة يُضاف بـ`version` أعلى.
    """
    DeadlineSchedule = apps.get_model("accounting_office", "DeadlineSchedule")
    DeadlineRule = apps.get_model("accounting_office", "DeadlineRule")
    TaxThreshold = apps.get_model("accounting_office", "TaxThreshold")

    for row in SEEDED_DETAILED_THRESHOLDS:
        TaxThreshold.objects.get_or_create(
            tax_system=row["tax_system"],
            kind=row["kind"],
            year=row["year"],
            defaults={"amount": row["amount"], "source_url": row["source_url"]},
        )

    for row in SEEDED_SCHEDULES:
        schedule, _created = DeadlineSchedule.objects.get_or_create(
            tax_system=row["tax_system"],
            year=row["year"],
            version=row["version"],
            defaults={
                "source_url": row["source_url"],
                "published_on": row["published_on"],
                "rest_day_policy": row["rest_day_policy"],
                "authority_closed_days": row["authority_closed_days"],
                "note": row["note"],
            },
        )
        for position, rule in enumerate(SEEDED_RULES[(row["tax_system"], row["year"])]):
            DeadlineRule.objects.get_or_create(
                schedule=schedule,
                code=rule["code"],
                defaults=_rule_defaults(rule, position),
            )


def unseed_deadline_schedules(apps, schema_editor):
    """عكسٌ يمحو ما زرعته هذه الهجرة وحدها — بمفاتيحه الطبيعية لا بأرقامه."""
    DeadlineSchedule = apps.get_model("accounting_office", "DeadlineSchedule")
    TaxThreshold = apps.get_model("accounting_office", "TaxThreshold")

    for row in SEEDED_SCHEDULES:
        DeadlineSchedule.objects.filter(
            tax_system=row["tax_system"], year=row["year"], version=row["version"],
        ).delete()
    for row in SEEDED_DETAILED_THRESHOLDS:
        TaxThreshold.objects.filter(
            tax_system=row["tax_system"], kind=row["kind"], year=row["year"],
        ).delete()


